mapper.select:
select id, rule_code, rule_name, metric_key, operator_type, threshold_value, effect_type, score_value, risk_tag, reason_template, enabled, sort_order, created_at, updated_at from risk_scoring_rule
where rule_code like concat('%', #{keyword}, '%') or rule_name like concat('%', #{keyword}, '%') or metric_key like concat('%', #{keyword}, '%') or ifnull(risk_tag, '') like concat('%', #{keyword}, '%')
order by sort_order, id limit #{limit} offset #{offset}

mapper.update:
update risk_scoring_rule
rule_code = #{body.rule_code}, rule_name = #{body.rule_name}, metric_key = #{body.metric_key}, operator_type = #{body.operator_type}, threshold_value = #{body.threshold_value}, effect_type = #{body.effect_type}, score_value = #{body.score_value}, risk_tag = #{body.risk_tag}, reason_template = #{body.reason_template}, enabled = #{body.enabled}, sort_order = #{body.sort_order},
where id = #{id}
